139	    /**
140	     * Generates a unique filename preserving the original extension.
141	     */
142	    private String generateFilename(MultipartFile file) {
143	        String originalFilename = file.getOriginalFilename();
144	        String ext = originalFilename != null && originalFilename.contains(".")
145	                ? originalFilename.substring(originalFilename.lastIndexOf("."))
146	                : ".png";
147	        return UUID.randomUUID().toString() + ext;
148	    }
