163	     */
164	    private Long getCurrentUserId() {
165	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
166	        if (authentication != null && authentication.isAuthenticated()) {
167	            String username = authentication.getName();
168	            // Re-extract from the JWT using the security context token
169	            try {
170	                String token = extractTokenFromContext();
171	                if (token != null) {
172	                    return jwtUtil.getUserIdFromToken(token);
173	                }
174	            } catch (Exception ex) {
175	                logger.warn("Could not extract userId from token: {}", ex.getMessage());
176	            }
177	        }
178	        return null;
179	    }
180	
181	    /**
182	     * Extracts the raw JWT from the current request's Authorization header.
183	     */
184	    private String extractTokenFromContext() {
185	        jakarta.servlet.http.HttpServletRequest request =
186	                ((org.springframework.web.context.request.ServletRequestAttributes)
187	                        org.springframework.web.context.request.RequestContextHolder.getRequestAttributes())
188	                        .getRequest();
189	        String bearer = request.getHeader("Authorization");
190	        if (bearer != null && bearer.startsWith("Bearer ")) {
191	            return bearer.substring(7);
192	        }
193	        return null;
