53	     * User Service via Feign to update the user's avatar URL.
54	     */
55	    @PostMapping("/avatar")
56	    public ResponseEntity<ApiResponse<Map<String, String>>> uploadAvatar(
57	            @RequestParam("file") MultipartFile file
58	    ) throws IOException {
59	        String username = getCurrentUsername();
60	
61	        // Validate file
62	        validateImageFile(file);
63	
64	        // Generate unique filename
65	        String filename = generateFilename(file);
66	
67	        // Save to uploads/avatars/
68	        Path uploadDir = UPLOAD_ROOT.resolve("avatars");
69	        Files.createDirectories(uploadDir);
70	        Path filePath = uploadDir.resolve(filename);
71	        file.transferTo(filePath.toFile());
72	
73	        String avatarUrl = "/uploads/avatars/" + filename;
74	
75	        // Call User Service to update avatar URL
76	        Long userId = getCurrentUserId();
77	        if (userId != null) {
78	            try {
79	                userServiceClient.updateAvatar(userId, new UpdateAvatarRequest(avatarUrl));
80	                logger.info("Avatar updated for user {} (userId={})", username, userId);
81	            } catch (Exception ex) {
82	                logger.error("Failed to update avatar in User Service for userId={}: {}", userId, ex.getMessage());
83	                // File is saved, but User Service update failed
84	                // Return success with a warning
85	                return ResponseEntity.ok(ApiResponse.success("Avatar uploaded but profile update may be delayed",
86	                        Map.of("avatarUrl", avatarUrl)));
87	            }
88	        }
89	
90	        return ResponseEntity.ok(ApiResponse.success("Avatar uploaded successfully",
91	                Map.of("avatarUrl", avatarUrl)));
92	    }
93	
94	    /**
95	     * Upload general image.
96	     * POST /api/upload/images
97	     * Validates the image and stores it under uploads/images/.
98	     */
99	    @PostMapping("/images")
100	    public ResponseEntity<ApiResponse<Map<String, String>>> uploadImage(
101	            @RequestParam("file") MultipartFile file
102	    ) throws IOException {
103	        getCurrentUsername(); // Verify authenticated
104	
105	        // Validate file
106	        validateImageFile(file);
107	
108	        // Generate unique filename
109	        String filename = generateFilename(file);
110	
111	        // Save to uploads/images/
112	        Path uploadDir = UPLOAD_ROOT.resolve("images");
113	        Files.createDirectories(uploadDir);
114	        Path filePath = uploadDir.resolve(filename);
115	        file.transferTo(filePath.toFile());
116	
117	        String url = "/uploads/images/" + filename;
118	        return ResponseEntity.ok(ApiResponse.success("Upload successful", Map.of("url", url)));
119	    }
