121	    /**
122	     * Validates that the uploaded file is an image within size limits.
123	     */
124	    private void validateImageFile(MultipartFile file) {
125	        if (file.isEmpty()) {
126	            throw new IllegalArgumentException("File is empty");
127	        }
128	
129	        String contentType = file.getContentType();
130	        if (contentType == null || !ALLOWED_CONTENT_TYPES.contains(contentType)) {
131	            throw new IllegalArgumentException("Only jpg/png/gif/webp images are supported");
132	        }
133	
134	        if (file.getSize() > MAX_IMAGE_SIZE) {
135	            throw new IllegalArgumentException("File size cannot exceed 2MB");
136	        }
137	    }
138	
139	    /**
140	     * Generates a unique filename preserving the original extension.
141	     */
142	    private String generateFilename(MultipartFile file) {
143	        String originalFilename = file.getOriginalFilename();
144	        String ext = originalFilename != null && originalFilename.contains(".")
145	                ? originalFilename.substring(originalFilename.lastIndexOf("."))
146	                : ".png";
147	        return UUID.randomUUID().toString() + ext;
148	    }
149	
150	    /**
151	     * Extracts the current authenticated username from Spring Security context.
152	     */
153	    private String getCurrentUsername() {
154	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
155	        if (authentication != null && authentication.isAuthenticated()) {
156	            return authentication.getName();
157	        }
158	        throw new UnauthorizedException("User not authenticated");
159	    }
160	
161	    /**
162	     * Extracts the current user ID from the JWT token in the request.
163	     */
164	    private Long getCurrentUserId() {
165	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
166	        if (authentication != null && authentication.isAuthenticated()) {
167	            String username = authentication.getName();
168	            // Re-extract from the JWT using the security context token
169	            try {
170	                String token = extractTokenFromContext();
171	                if (token != null) {
172	                    return jwtUtil.getUserIdFromToken(token);
173	                }
174	            } catch (Exception ex) {
175	                logger.warn("Could not extract userId from token: {}", ex.getMessage());
176	            }
177	        }
178	        return null;
179	    }
180	
181	    /**
182	     * Extracts the raw JWT from the current request's Authorization header.
183	     */
184	    private String extractTokenFromContext() {
185	        jakarta.servlet.http.HttpServletRequest request =
186	                ((org.springframework.web.context.request.ServletRequestAttributes)
187	                        org.springframework.web.context.request.RequestContextHolder.getRequestAttributes())
188	                        .getRequest();
189	        String bearer = request.getHeader("Authorization");
190	        if (bearer != null && bearer.startsWith("Bearer ")) {
191	            return bearer.substring(7);
192	        }
193	        return null;
194	    }
195	}
