1	import { type ReactNode, createContext, useContext, useState, useEffect } from 'react';
2	
3	interface User {
4	  username: string;
5	  email: string;
6	  role?: string;
7	  avatarUrl?: string | null;
8	}
9	
10	interface AuthContextType {
11	  user: User | null;
12	  isAuthenticated: boolean;
13	  isAdmin: boolean;
14	  login: (username: string, accessToken: string, role?: string, avatarUrl?: string | null) => void;
15	  updateUserAvatar: (avatarUrl: string | null) => void;
16	  logout: () => void;
17	}
18	
19	const AuthContext = createContext<AuthContextType | undefined>(undefined);
20	
21	export function AuthProvider({ children }: { children: ReactNode }) {
22	  const [user, setUser] = useState<User | null>(null);
23	  const [isAuthenticated, setIsAuthenticated] = useState(false);
24	  const [isAdmin, setIsAdmin] = useState(false);
25	
26	  useEffect(() => {
27	    const token = localStorage.getItem('access_token');
28	    const storedUser = localStorage.getItem('user');
29	
30	    if (token && storedUser) {
31	      try {
32	        const userData = JSON.parse(storedUser);
33	        setUser(userData);
34	        setIsAuthenticated(true);
35	        setIsAdmin(userData.role === 'ADMIN');
36	      } catch {
37	        localStorage.removeItem('user');
38	        localStorage.removeItem('access_token');
39	      }
40	    }
41	  }, []);
42	
43	  const login = (username: string, accessToken: string, role: string = 'USER', avatarUrl?: string | null) => {
44	    const userData: User = { username, email: '', role, avatarUrl };
45	    setUser(userData);
46	    setIsAuthenticated(true);
47	    setIsAdmin(role === 'ADMIN');
48	    localStorage.setItem('access_token', accessToken);
49	    localStorage.setItem('user', JSON.stringify(userData));
50	  };
51	
52	  const updateUserAvatar = (avatarUrl: string | null) => {
53	    setUser(prev => {
54	      if (!prev) return prev;
55	      return { ...prev, avatarUrl };
56	    });
57	  };
58	
59	  useEffect(() => {
60	    if (user) {
61	      localStorage.setItem('user', JSON.stringify(user));
62	    }
63	  }, [user]);
64	
65	  const logout = () => {
66	    setUser(null);
67	    setIsAuthenticated(false);
68	    setIsAdmin(false);
69	    localStorage.removeItem('access_token');
70	    localStorage.removeItem('refresh_token');
71	    localStorage.removeItem('user');
72	  };
73	
74	  return (
75	    <AuthContext.Provider value={{ user, isAuthenticated, isAdmin, login, logout, updateUserAvatar }}>
76	      {children}
77	    </AuthContext.Provider>
78	  );
79	}
80	
81	export function useAuth() {
82	  const context = useContext(AuthContext);
83	  if (context === undefined) {
84	    throw new Error('useAuth must be used within an AuthProvider');
85	  }
86	  return context;
87	}
