1	import axios, { type AxiosError, type InternalAxiosRequestConfig } from 'axios';
2	import { mockRequestAdapter } from './mockDb';
3	
4	/**
5	 * Axios client configuration
6	 * Communicates with backend API
7	 */
8	
9	const client = axios.create({
10	  baseURL: import.meta.env.VITE_API_URL || '/api',
11	  timeout: 10000,
12	});
13	
14	/**
15	 * Request interceptor - auto-attach JWT token and override adapter for mock
16	 */
17	client.interceptors.request.use(
18	  (config: InternalAxiosRequestConfig) => {
19	    if (localStorage.getItem('use_mock') === 'true') {
20	      config.adapter = mockRequestAdapter as any;
21	    }
22	    const token = localStorage.getItem('access_token');
23	    if (token && config.headers) {
24	      config.headers.Authorization = `Bearer ${token}`;
25	    }
26	    if (config.data instanceof FormData) {
27	      delete config.headers['Content-Type'];
28	    } else {
29	      config.headers['Content-Type'] = 'application/json';
30	    }
31	    return config;
32	  },
33	  (error) => {
34	    return Promise.reject(error);
35	  }
36	);
37	
38	/**
39	 * Tracks whether a token refresh is currently in progress.
40	 * Used to prevent multiple concurrent 401 responses from triggering
41	 * multiple refresh requests simultaneously.
42	 */
43	let isRefreshing = false;
44	let failedQueue: Array<{
45	  resolve: (token: string) => void;
46	  reject: (error: unknown) => void;
47	}> = [];
48	
49	/**
50	 * Processes all queued requests that failed due to 401,
51	 * either retrying them with the new token or rejecting them.
52	 */
53	function processQueue(error: unknown, token: string | null) {
54	  failedQueue.forEach((prom) => {
55	    if (error) {
56	      prom.reject(error);
57	    } else {
58	      prom.resolve(token!);
59	    }
60	  });
61	  failedQueue = [];
62	}
63	
64	/**
65	 * Response interceptor - handle 401 with token refresh
66	 *
67	 * On 401:
68	 * 1. If not already refreshing, attempt to refresh the token
69	 * 2. If refresh succeeds, update stored tokens and retry the original request
70	 * 3. If refresh fails, clear tokens and redirect to login
71	 * 4. If already refreshing, queue the request to be retried after refresh completes
72	 */
73	client.interceptors.response.use(
74	  (response) => response,
75	  async (error: AxiosError) => {
76	    // Detect server offline / connection error and fallback to mock mode
77	    // Retry once after a short delay to avoid false positives from CORS preflight timing
78	    if ((error.code === 'ERR_NETWORK' || !error.response) && localStorage.getItem('use_mock') !== 'true') {
79	      const config = error.config as InternalAxiosRequestConfig & { _networkRetry?: boolean };
80	      if (!config._networkRetry) {
81	        config._networkRetry = true;
82	        await new Promise((r) => setTimeout(r, 500));
83	        return client(config);
84	      }
85	      localStorage.setItem('use_mock', 'true');
86	      window.dispatchEvent(new Event('mock-mode-changed'));
87	      window.location.reload();
88	      return new Promise(() => {}); // Keep request pending during reload
89	    }
90	
91	    const originalRequest = error.config as InternalAxiosRequestConfig & { _retry?: boolean };
92	
93	    // Only attempt refresh for 401 errors on non-auth endpoints
94	    if (error.response?.status === 401 && !originalRequest._retry) {
95	      // Don't try to refresh if the failing request is itself a refresh request
96	      if (originalRequest.url === '/auth/refresh') {
97	        clearTokensAndRedirect();
98	        return Promise.reject(error);
99	      }
