1	import { useState, useEffect, useRef, type FormEvent } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
4	import { useAuth } from '../context/AuthContext';
5	import { getMyProfile, updateProfile, uploadAvatar } from '../api/user';
6	import { queryKeys } from '../lib/queryKeys';
7	import Breadcrumbs from '../components/Breadcrumbs';
8	
9	const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'image/webp'];
10	const MAX_SIZE = 2 * 1024 * 1024; // 2MB
11	
12	export default function ProfileEditPage() {
13	  const { user, updateUserAvatar } = useAuth();
14	  const navigate = useNavigate();
15	  const queryClient = useQueryClient();
16	  const fileInputRef = useRef<HTMLInputElement>(null);
17	
18	  const [currentAvatarUrl, setCurrentAvatarUrl] = useState('');
19	  const [isUploading, setIsUploading] = useState(false);
20	  const [bio, setBio] = useState('');
21	  const [location, setLocation] = useState('');
22	  const [website, setWebsite] = useState('');
23	  const [error, setError] = useState('');
24	
25	  const { data: profile, isLoading } = useQuery({
26	    queryKey: queryKeys.users.me(),
27	    queryFn: getMyProfile,
28	  });
29	
30	  useEffect(() => {
31	    if (profile) {
32	      setCurrentAvatarUrl(profile.avatarUrl || '');
33	      setBio(profile.bio || '');
34	      setLocation(profile.location || '');
35	      setWebsite(profile.website || '');
36	    }
37	  }, [profile]);
38	
39	  const updateMutation = useMutation({
40	    mutationFn: async () => {
41	      return await updateProfile({
42	        avatarUrl: currentAvatarUrl || undefined,
43	        bio: bio.trim() || undefined,
44	        location: location.trim() || undefined,
45	        website: website.trim() || undefined,
46	      });
47	    },
48	    onSuccess: (data) => {
49	      queryClient.invalidateQueries({ queryKey: queryKeys.users.me() });
50	      if (user) {
51	        queryClient.invalidateQueries({ queryKey: queryKeys.users.detail(user.username) });
52	        // Avatar changed — invalidate posts/comments so they re-fetch with new URL
53	        queryClient.invalidateQueries({ queryKey: queryKeys.posts.all });
54	        queryClient.invalidateQueries({ queryKey: queryKeys.comments.all });
55	        updateUserAvatar(data.avatarUrl ?? null);
56	        navigate(`/profile/${user.username}`);
57	      }
58	    },
59	    onError: (err: any) => {
60	      setError(err.response?.data?.message || '更新失败，请重试');
61	    },
62	  });
63	
64	  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
65	    const file = e.target.files?.[0];
66	    if (!file) return;
67	
68	    setError('');
69	
70	    if (!ALLOWED_TYPES.includes(file.type)) {
71	      setError('仅支持 JPG、PNG、WebP 格式的图片');
72	      return;
73	    }
74	
75	    if (file.size > MAX_SIZE) {
76	      setError('文件大小不能超过 2MB');
77	      return;
78	    }
79	
80	    try {
81	      setIsUploading(true);
82	      const url = await uploadAvatar(file);
83	      setCurrentAvatarUrl(url);
84	      // 头像上传成功后自动保存 profile，避免用户忘记保存导致孤立文件
85	      updateMutation.mutate();
86	    } catch (err: any) {
87	      setError(err.response?.data?.message || '图片上传失败，请重试');
88	    } finally {
89	      setIsUploading(false);
90	      if (fileInputRef.current) {
91	        fileInputRef.current.value = '';
92	      }
93	    }
94	  };
95	
96	  const handleSubmit = (e: FormEvent) => {
97	    e.preventDefault();
98	    setError('');
99	    updateMutation.mutate();
100	  };
101	
102	  const handleCancel = () => {
103	    if (user) {
104	      navigate(`/profile/${user.username}`);
105	    }
106	  };
107	
108	  if (isLoading) {
109	    return (
110	      <div style={{ textAlign: 'center', padding: '5rem 0' }}>
111	        <div className="spinner"></div>
112	        <p style={{ marginTop: '1.25rem', color: 'var(--text-muted)' }}>加载中...</p>
113	      </div>
114	    );
